cases.script:
printf 'payload-line\n' > f1
exec 3<f1
count() { local g=(/proc/self/fd/*); REPLY=${#g[@]}; }
msg() { local e; e=$(< err.txt); e=${e#*recv-fd: }; e=${e//[0-9][0-9][0-9][0-9]*,/N,}; printf '%s' "$e"; }
msg() { local e; e=$(< err.txt)
  case $e in
    *"peer uid mismatch (got 2000, want "*) printf 'uid-mismatch(got 2000)';;
    *"peer gid mismatch (got 2000, want "*) printf 'gid-mismatch(got 2000)';;
    *"peer pid mismatch (got "*) printf 'pid-mismatch';;
    *"bad --peer-"*) printf 'bad-arg';;
    *"unexpected"*) printf 'unexpected-arg';;
    '') printf 'none';;
    *) printf 'other';; esac; }
scm pair -h A -h B
count; n0=$REPLY
ok() { local l=$1; shift; exec 3<&-; exec 3<f1; scm send-fd $A 3 tok; scm recv-fd $B "$@" -h got 2>err.txt; local rc=$?
  count; local n1=$REPLY; local data=none
  if ((rc==0)); then read -r data <&$got; exec {got}<&-; fi
  printf '%s status=%s err=%s fds=%s data=%s\n' "$l" $rc "$(msg)" $((n1-n0)) "$data"; }
ok uid-only --peer-uid 2000
ok gid-only --peer-gid 2000
ok pid-only --peer-pid $$
ok all-three --peer-uid 2000 --peer-gid 2000 --peer-pid $$
ok no-filter
ok with-token --token tok

printf 'payload-line\n' > f1
exec 3<f1
count() { local g=(/proc/self/fd/*); REPLY=${#g[@]}; }
msg() { local e; e=$(< err.txt); e=${e#*recv-fd: }; e=${e//[0-9][0-9][0-9][0-9]*,/N,}; printf '%s' "$e"; }
