    *"peer gid mismatch (got 2000, want "*) printf 'gid-mismatch(got 2000)';;
    *"peer pid mismatch (got "*) printf 'pid-mismatch';;
    *"bad --peer-"*) printf 'bad-arg';;
    *"unexpected"*) printf 'unexpected-arg';;
    '') printf 'none';;
    *) printf 'other';; esac; }
scm pair -h A -h B
count; n0=$REPLY
bad() { local l=$1; shift; scm send-fd $A 3 tok; scm recv-fd $B "$@" -h got 2>err.txt; local rc=$?
  count; local n1=$REPLY
  printf '%s status=%s err=%s leaked-fds=%s got-bound=%s\n' "$l" $rc "$(msg)" $((n1-n0)) "${got-unset}"; unset got; }
bad wrong-uid --peer-uid 2001
bad wrong-uid-zero --peer-uid 0
bad wrong-gid --peer-gid 2001
bad wrong-pid --peer-pid $(($$+1))
bad right-uid-wrong-gid --peer-uid 2000 --peer-gid 2001
bad right-uid-gid-wrong-pid --peer-uid 2000 --peer-gid 2000 --peer-pid $(($$+1))
scm send-fd $A 3 tok; scm recv-fd $B --peer-uid 2000 --peer-gid 2000 --peer-pid $$ -h got 2>err.txt; rc=$?
read -r data <&$got
printf 'after-rejections status=%s data=%s\n' $rc "$data"

printf 'payload-line\n' > f1
exec 3<f1
count() { local g=(/proc/self/fd/*); REPLY=${#g[@]}; }
msg() { local e; e=$(< err.txt); e=${e#*recv-fd: }; e=${e//[0-9][0-9][0-9][0-9]*,/N,}; printf '%s' "$e"; }
msg() { local e; e=$(< err.txt)
  case $e in
    *"peer uid mismatch (got 2000, want "*) printf 'uid-mismatch(got 2000)';;
    *"peer gid mismatch (got 2000, want "*) printf 'gid-mismatch(got 2000)';;
    *"peer pid mismatch (got "*) printf 'pid-mismatch';;
    *"bad --peer-"*) printf 'bad-arg';;
    *"unexpected"*) printf 'unexpected-arg';;
    '') printf 'none';;
    *) printf 'other';; esac; }
scm pair -h A -h B
count; n0=$REPLY
mal() { local l=$1; shift; scm send-fd $A 3 tok; scm recv-fd $B "$@" 2>err.txt; local rc=$?
  printf '%s status=%s err=%s\n' "$l" $rc "$(msg)"
  # malformed arguments are rejected before the message is consumed: drain it with a valid receive
  scm recv-fd $B -h drained 2>/dev/null; exec {drained}<&-; unset drained; }
mal uid-alpha --peer-uid abc
mal uid-trailing --peer-uid 12x
mal uid-empty --peer-uid ''
mal uid-negative --peer-uid -1
mal uid-over-32-bit --peer-uid 4294967296
mal gid-alpha --peer-gid abc
mal gid-over-32-bit --peer-gid 4294967296
mal pid-alpha --peer-pid abc
mal pid-over-int --peer-pid 2147483648
mal pid-negative --peer-pid -5
mal uid-missing-value --peer-uid
count; echo "fds-delta=$((REPLY-n0))"

files.inner.sh:
printf 'payload-line\n' >/dev/null
count() { local g=(/proc/self/fd/*); REPLY=${#g[@]}; }
msg() { local e; e=$(< err.txt)
  case $e in
    *"peer uid mismatch (got 4242, want "*) printf 'uid-mismatch(got 4242)';;
    *"peer gid mismatch (got 4343, want "*) printf 'gid-mismatch(got 4343)';;
    *"peer pid mismatch"*) printf 'pid-mismatch';;
    '') printf 'none';; *) printf 'other';; esac; }
count; n0=$REPLY
try() { local l=$1; shift; exec {F2}<f1; scm send-fd $A $F2 tok; scm recv-fd $B "$@" -h got 2>err.txt; local rc=$?
  local d=none; ((rc==0)) && { read -r d <&$got; exec {got}<&-; }
  exec {F2}<&-; count
  printf '%s status=%s err=%s leaked=%s data=%s\n' "$l" $rc "$(msg)" $((REPLY-n0)) "$d"; }
try distinct-uid --peer-uid 4242
try distinct-gid --peer-gid 4343
try distinct-all --peer-uid 4242 --peer-gid 4343 --peer-pid $$
try receiver-own-uid-rejected --peer-uid 0
try receiver-own-gid-rejected --peer-gid 0
try same-uid-claim-rejected --peer-uid 0 --peer-gid 4343
